eventBus.on('test', () => {
  called = true;
});
count = eventBus.emit('test');
console.assert(count === 1, 'emit with one listener should return 1');
console.assert(called === true, 'listener should have been called');

// Reset for next test
called = false;

// Test 3: Add multiple listeners and emit
