const { LRUCache } = require('./s5_cache.js');

// Test 1: Basic get/set functionality
console.log("Test 1: Basic get/set functionality");
const cache = new LRUCache(2);

cache.set('a', 1);
cache.set('b', 2);
console.assert(cache.get('a') === 1, "get('a') should return 1");
console.assert(cache.get('b') === 2, "get('b') should return 2");
console.log("✓ Basic get/set works");

// Test 2: Capacity limit
console.log("Test 2: Capacity limit");
cache.set('c', 3);
console.assert(cache.get('a') === undefined, "get('a') should be undefined after capacity exceeded");
console.assert(cache.get('b') === 2, "get('b') should still return 2");
console.assert(cache.get('c') === 3, "get('c') should return 3");
console.log("✓ Capacity limit works");

// Test 3: LRU eviction
console.log("Test 3: LRU eviction");
const cache2 = new LRUCache(3);
cache2.set('a', 1);
cache2.set('b', 2);
cache2.set('c', 3);
cache2.get('a'); // Access 'a' to make it most recently used
cache2.set('d', 4); // This should evict 'b' (least recently used)
console.assert(cache2.get('a') === 1, "get('a') should still return 1");
console.assert(cache2.get('b') === undefined, "get('b') should be undefined after eviction");
console.assert(cache2.get('c') === 3, "get('c') should still return 3");
console.assert(cache2.get('d') === 4, "get('d') should return 4");
console.log("✓ LRU eviction works");

// Test 4: Update existing key
console.log("Test 4: Update existing key");
const cache3 = new LRUCache(2);
cache3.set('a', 1);
cache3.set('b', 2);
cache3.set('a', 10); // Update existing key
console.assert(cache3.get('a') === 10, "get('a') should return updated value 10");
console.assert(cache3.get('b') === 2, "get('b') should still return 2");
console.log("✓ Update existing key works");

// Test 5: Get non-existent key
console.log("Test 5: Get non-existent key");
const cache4 = new LRUCache(2);
console.assert(cache4.get('nonexistent') === undefined, "get('nonexistent') should return undefined");
console.log("✓ Get non-existent key works");

// Test 6: TTL functionality
console.log("Test 6: TTL functionality");
const cache5 = new LRUCache(2, () => 0); // Fixed time for testing
cache5.set('a', 1, 100); // Expires in 100ms
cache5.set('b', 2, 200); // Expires in 200ms
console.assert(cache5.get('a') === 1, "get('a') should return 1");
console.assert(cache5.get('b') === 2, "get('b') should return 2");

// Advance time to just before expiry
const cache6 = new LRUCache(2, () => 50);
cache6.set('c', 3, 100);
console.assert(cache6.get('c') === 3, "get('c') should return 3 before expiry");

// Advance time to after expiry
const cache7 = new LRUCache(2, () => 0);
cache7.set('d', 4, 100);
cache7.now = () => 200; // Simulate time passing
console.assert(cache7.get('d') === undefined, "get('d') should return undefined after expiry");

// Test that non-expiring entries still work
const cache8 = new LRUCache(2, () => 0);
cache8.set('e', 5); // No TTL
console.assert(cache8.get('e') === 5, "get('e') should return 5 (no TTL)");
cache8.now = () => 1000; // Advance time significantly
console.assert(cache8.get('e') === 5, "get('e') should still return 5 after long time (no TTL)");

console.log("✓ TTL functionality works");

console.log("All tests passed!");
// Test 7: Stats functionality
console.log("Test 7: Stats functionality");
const statsCache = new LRUCache(3);
console.assert(statsCache.stats().hits === 0, "Initial hits should be 0");
console.assert(statsCache.stats().misses === 0, "Initial misses should be 0");
console.assert(statsCache.stats().evictions === 0, "Initial evictions should be 0");

statsCache.set('a', 1);
statsCache.set('b', 2);
statsCache.set('c', 3);
console.assert(statsCache.stats().hits === 0, "After setting, hits should still be 0");
console.assert(statsCache.stats().misses === 0, "After setting, misses should still be 0");
console.assert(statsCache.stats().evictions === 0, "After setting, evictions should still be 0");

statsCache.get('a');
console.assert(statsCache.stats().hits === 1, "After getting existing item, hits should be 1");
console.assert(statsCache.stats().misses === 0, "After getting existing item, misses should still be 0");
console.assert(statsCache.stats().evictions === 0, "After getting existing item, evictions should still be 0");

statsCache.get('d');
console.assert(statsCache.stats().hits === 1, "After getting non-existing item, hits should still be 1");
console.assert(statsCache.stats().misses === 1, "After getting non-existing item, misses should be 1");
console.assert(statsCache.stats().evictions === 0, "After getting non-existing item, evictions should still be 0");

statsCache.set('d', 4);
console.assert(statsCache.stats().hits === 1, "After eviction, hits should still be 1");
console.assert(statsCache.stats().misses === 1, "After eviction, misses should still be 1");
console.assert(statsCache.stats().evictions === 1, "After eviction, evictions should be 1");

console.log("✓ Stats functionality works");

console.log("All tests passed!");

