        if (k !== i) {
          const row = [];
          for (let l = 0; l < cols; l++) {
            if (l !== j) {
              row.push(m[k][l]);
            }
          }
          minor.push(row);
        }
      }
      
      // Calculate cofactor: (-1)^(i+j) * determinant of minor
      const sign = Math.pow(-1, i + j);
      cofactorMatrix[i][j] = sign * determinant(minor);
    }
  }
  
  // Transpose the cofactor matrix to get the adjugate
  const adjugate = transpose(cofactorMatrix);
  
  // Divide each element by the determinant
  const result = [];
  for (let i = 0; i < rows; i++) {
    result[i] = [];
    for (let j = 0; j < cols; j++) {
      result[i][j] = adjugate[i][j] / det;
    }
  }
  
  return result;
}

module.exports = { add, multiply, transpose, identity, determinant, inverse };

start.s5_cache.js:
class LRUCache {
  constructor(capacity, now = Date.now) {
    this.capacity = capacity;
    this.now = now;
    this.cache = new Map();
    this.hits = 0;
    this.misses = 0;
    this.evictions = 0;
  }

  get(key) {
    if (!this.cache.has(key)) {
      this.misses++;
      return undefined;
    }
    
    const entry = this.cache.get(key);
    // Check if the entry has expired
    if (entry.expiry !== undefined && this.now() > entry.expiry) {
      this.cache.delete(key);
      this.misses++;
      return undefined;
    }
    
    // Move the key to the end (mark as most recently used)
    const value = entry.value;
    this.cache.delete(key);
    this.cache.set(key, entry);
    this.hits++;
    
    return value;
  }

  set(key, value, ttlMs) {
    // If key already exists, update it and move to end
    if (this.cache.has(key)) {
      this.cache.delete(key);
    } else if (this.cache.size >= this.capacity) {
      // Remove the least recently used item (first item in Map)
      const firstKey = this.cache.keys().next().value;
      this.cache.delete(firstKey);
      this.evictions++;
    }
    
    // Add the new key-value pair with optional expiry
    const entry = { value };
    if (ttlMs !== undefined) {
      entry.expiry = this.now() + ttlMs;
    }
    this.cache.set(key, entry);
  }
  
  delete(key) {
    if (this.cache.has(key)) {
      this.cache.delete(key);
      return true;
    }
    return false;
  }
  
  clear() {
    this.cache.clear();
  }
  
  stats() {
    return {
      hits: this.hits,
      misses: this.misses,
      evictions: this.evictions
    };
  }
}

module.exports = { LRUCache };

