class TodoList:
    def __init__(self):
        self.todos = []
        self.next_id = 1

    def add(self, title):
        todo_id = self.next_id
        self.next_id += 1
        self.todos.append({'id': todo_id, 'title': title, 'done': False})
        return todo_id
    def done(self, item_id):
        for todo in self.todos:
            if todo['id'] == item_id:
                todo['done'] = True
                break

