        // Handle minus operator - either binary or unary
        // If we have only one element on stack, it's unary minus
        if (stack.length === 1) {
          const a = stack.pop();
          stack.push(-a);
        } else {
          // Binary minus
          if (stack.length < 2) {
            throw new Error('Invalid expression');
          }
          const b = stack.pop();
          const a = stack.pop();
          stack.push(a - b);
        }
      } else if (token === '^') {
        // Handle power operator
        if (stack.length < 2) {
          throw new Error('Invalid expression');
        }
        const b = stack.pop();
        const a = stack.pop();
        stack.push(Math.pow(a, b));
      }
    }
  }
  
  if (stack.length !== 1) {
    throw new Error('Invalid expression');
  }
  
  return stack[0];
}

module.exports = { tokenize, evaluate };

